namespace fs=std::filesystem;
Json checks=Json::array();
void check(bool ok,const std::string&name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);}
struct Q {int e;mfem::IntegrationPoint ip;PicVector position;};
std::vector<Q> quadrature(const GapPicOptions&o){std::vector<Q>q;double a=.5-.5/std::sqrt(3.),b=1-a;for(int j=0;j<o.ny;++j)for(int i=0;i<o.nx;++i)for(double y:{a,b})for(double x:{a,b}){Q p;p.e=j*o.nx+i;p.ip.Set2(x,y);p.position={(i+x)*o.width_m/o.nx,(j+y)*o.gap_m/o.ny,0};q.push_back(p);}return q;}
Json species(const CoupledPic&c){std::array<double,2>N{},Q{},K{};std::array<int,2>count{};for(const auto&p:const_cast<CoupledPic&>(c).native().particles()){int s=c.tags().at(p.id).species;N[s]+=p.weight;Q[s]+=p.weight*p.charge_C;K[s]+=p.weight*pic_kinetic_energy_J(p);++count[s];}return {{"macros",count},{"physical_count",N},{"charge_C",Q},{"kinetic_J",K}};}
Json zero_and_pair(){GapPicOptions o;o.nx=3;o.ny=12;o.width_m=.0001;o.gap_m=.0004;o.depth_m=.025;o.lower_potential_V=.02;o.upper_potential_V=-.02;CoupledPic vacuum(o,proton_mass/pic_me);vacuum.native().solve_fields();double maxerr=0;for(auto&q:quadrature(o)){auto E=vacuum.native().electric_field(q.position[0],q.position[1]);maxerr=std::max(maxerr,std::abs(E[1]-.04/o.gap_m));maxerr=std::max(maxerr,std::abs(E[0]));}check(maxerr<1e-8,"zero-density native vacuum field");
 CoupledPic balanced(o,proton_mass/pic_me);std::vector<GapParticle> p;std::vector<int>s;std::vector<PicVector>r;for(auto&q:quadrature(o))for(int k=0;k<2;++k){GapParticle z;z.position_m=q.position;z.weight=12345.;z.charge_C=k?pic_e:-pic_e;z.mass_kg=k?pic_me*balanced.ratio():pic_me;p.push_back(z);s.push_back(k);r.push_back(z.position_m);}balanced.authored("co-located-neutral-static-pairs",p,s,r);balanced.native().solve_fields();double difference=0;for(auto&q:quadrature(o)){auto E=balanced.native().electric_field(q.position[0],q.position[1]),F=vacuum.native().electric_field(q.position[0],q.position[1]);for(int k=0;k<3;++k)difference=std::max(difference,std::abs(E[k]-F[k]));}auto d=balanced.native().diagnostics();auto sums=species(balanced);check(d.particle_charge_C==0&&d.deposited_charge_C==0,"co-located signed charge cancels exactly in deposition");check(difference==0,"co-located e/ion pair leaves native vacuum field bitwise unchanged");check(sums["physical_count"][0]==sums["physical_count"][1],"balanced physical species counts");
 o.lower_potential_V=o.upper_potential_V=0;CoupledPic moving(o,proton_mass/pic_me);for(auto&z:p)z.proper_velocity_m_s={1e3,2e3,0};moving.authored("common-velocity-neutral-pairs",p,s,r);moving.native().solve_fields();auto before=species(moving);for(int i=0;i<32;++i)moving.advance(1e-14);auto after=species(moving);auto dm=moving.native().diagnostics();check(before==after,"closed neutral transport preserves each species count charge and kinetic energy");check(dm.particle_charge_C==0&&dm.deposited_charge_C==0&&dm.field_energy_J==0,"moving co-located e/ion pairs retain zero net self field");check(moving.native().particles().size()==p.size(),"closed neutral transport retains all macro IDs/counts");return {{"family","vacuum_and_cancellation"},{"vacuum_field_max_absolute_error_V_m",maxerr},{"balanced_vs_vacuum_max_field_difference_V_m",difference},{"balanced_species",sums},{"moving_before",before},{"moving_after",after},{"moving_steps",32},{"moving_dt_s",1e-14},{"moving_gauss_defect_C",dm.gauss_defect_C},{"moving_continuity_defect_C",dm.maximum_nodal_continuity_defect_C}};
}
Json slab(double n,double Te,int ny,const fs::path&out){double lambda=std::sqrt(eps*Te/(n*pic_e)),V0=.01*Te;GapPicOptions o;o.nx=2;o.ny=ny;o.width_m=lambda;o.gap_m=4*lambda;o.depth_m=.025;o.lower_potential_V=V0;o.upper_potential_V=-V0;const double volume=o.width_m*o.gap_m*o.depth_m,N0=n*volume;auto q=quadrature(o);double w0=N0/q.size();std::vector<double>guess(q.size());for(std::size_t i=0;i<q.size();++i)guess[i]=V0*(1-2*q[i].position[1]/o.gap_m);std::unique_ptr<CoupledPic>accepted;double defect=0,max_count=0,max_gauss=0,max_poisson=0,max_perturbation=0;int iterations=0;
 for(int iteration=0;iteration<160;++iteration){double mean=0;for(double v:guess)mean+=v;mean/=guess.size();auto candidate=std::make_unique<CoupledPic>(o,proton_mass/pic_me);std::vector<GapParticle>ps;std::vector<int>sp;std::vector<PicVector>reference;for(std::size_t i=0;i<q.size();++i){double perturb=(guess[i]-mean)/Te;max_perturbation=std::max(max_perturbation,std::abs(perturb));if(std::abs(perturb)>=.010000001)throw std::runtime_error("linear response amplitude rejected");for(int s=0;s<2;++s){GapParticle p;p.position_m=q[i].position;p.weight=w0*(s?1:1+perturb);p.charge_C=s?pic_e:-pic_e;p.mass_kg=s?pic_me*candidate->ratio():pic_me;ps.push_back(p);sp.push_back(s);reference.push_back(p.position_m);}}candidate->authored("static-fixed-N-linear-response",ps,sp,reference);candidate->native().solve_fields();auto totals=species(*candidate);for(int s=0;s<2;++s)max_count=std::max(max_count,std::abs(totals["physical_count"][s].get<double>()/N0-1));auto d=candidate->native().diagnostics();max_gauss=std::max(max_gauss,std::abs(d.gauss_defect_C)/(2*pic_e*N0));max_poisson=std::max(max_poisson,d.poisson_residual_C_per_m);defect=0;std::vector<double>sample(q.size());for(std::size_t i=0;i<q.size();++i){sample[i]=candidate->native().potential().GetValue(q[i].e,q[i].ip);defect=std::max(defect,std::abs(sample[i]-guess[i])/V0);}iterations=iteration+1;accepted=std::move(candidate);if(defect<2e-12)break;for(std::size_t i=0;i<q.size();++i)guess[i]=.65*guess[i]+.35*sample[i];}
 check(max_perturbation<.010000001,"linear response amplitude admitted");check(defect<2e-12,"native Poisson / fixed-N susceptibility iteration converged");check(max_count<2e-13,"each static response species retains its fixed total physical count");check(max_gauss<2e-12,"native response Gauss closure relative to gross species charge");double pnum=0,pden=0,enum0=0,eden=0,lateral=0;double A=o.gap_m/(2*lambda);for(auto&point:q){double y=point.position[1],exact=V0*std::sinh((o.gap_m/2-y)/lambda)/std::sinh(A),ey=V0/lambda*std::cosh((o.gap_m/2-y)/lambda)/std::sinh(A),phi=accepted->native().potential().GetValue(point.e,point.ip);auto E=accepted->native().electric_field(point.position[0],y);pnum+=(phi-exact)*(phi-exact);pden+=exact*exact;enum0+=(E[1]-ey)*(E[1]-ey);eden+=ey*ey;lateral=std::max(lateral,std::abs(E[0]));}double pe=std::sqrt(pnum/pden),ee=std::sqrt(enum0/eden);check(pe<.006&&ee<.09,"linear Debye slab matches independent continuum shape");check(lateral/(V0/lambda)<1e-9,"slab lateral field is negligible relative to physical field scale");std::string stem="n"+std::to_string(static_cast<long long>(n))+"_T"+std::to_string(static_cast<int>(Te))+"_ny"+std::to_string(ny);std::ofstream f(out/(stem+".csv"));f<<std::setprecision(17)<<"y_m,phi_native_V,phi_linear_reference_V,Ey_native_V_m,Ey_linear_reference_V_m\n";for(int j=0;j<ny;++j){mfem::IntegrationPoint ip;ip.Set2(.5,.5);double y=(j+.5)*o.gap_m/ny,exact=V0*std::sinh((o.gap_m/2-y)/lambda)/std::sinh(A),ey=V0/lambda*std::cosh((o.gap_m/2-y)/lambda)/std::sinh(A);auto E=accepted->native().electric_field(o.width_m/2,y);f<<y<<','<<accepted->native().potential().GetValue(j*o.nx,ip)<<','<<exact<<','<<E[1]<<','<<ey<<'\n';}auto mid=accepted->native().electric_field(o.width_m/2,o.gap_m/2);double vacuum=2*V0/o.gap_m;double wp=std::sqrt(n*pic_e*pic_e/(eps*pic_me));return {{"family","linear_Debye_slab"},{"density_cm3",n/1e6},{"electron_temperature_parameter_eV",Te},{"lambda_D_m",lambda},{"nx",o.nx},{"ny",ny},{"dx_m",o.width_m/o.nx},{"dy_m",o.gap_m/ny},{"lambda_over_dy",lambda/(o.gap_m/ny)},{"length_over_lambda",4},{"boundary_potentials_V",{V0,-V0}},{"max_abs_e_phi_over_Te",.01},{"response_iterations",iterations},{"response_fixed_point_relative_defect",defect},{"phi_relative_L2_error",pe},{"electric_relative_L2_error",ee},{"max_lateral_E_V_m",lateral},{"max_lateral_E_relative_to_V0_over_lambda",lateral/(V0/lambda)},{"midplane_E_over_vacuum",mid[1]/vacuum},{"midplane_E_over_vacuum_reference",A/std::sinh(A)},{"max_species_number_relative_defect",max_count},{"max_gauss_relative_to_gross_charge",max_gauss},{"max_native_poisson_residual_C_per_m",max_poisson},{"species",species(*accepted)},{"omega_pe_rad_s",wp},{"plasma_period_s",2*std::numbers::pi/wp},{"hypothetical_dt_s",1e-14},{"hypothetical_dt_omega_pe",1e-14*wp},{"profiles_csv",stem+".csv"},{"closure","fixed-N linear isothermal Maxwell-Boltzmann electrons; immobile uniform positive ions"},{"particle_time_advance_in_this_case",false}};
}
int main(int argc,char**argv){try{
#ifdef MFEM_USE_MPI
 mfem::Mpi::Init(argc,argv);mfem::Hypre::Init();
#endif
 cpu_set_t affinity;CPU_ZERO(&affinity);require(sched_getaffinity(0,sizeof(affinity),&affinity)==0&&CPU_COUNT(&affinity)==1&&CPU_ISSET(7,&affinity),"CPU7 affinity required");require(getpriority(PRIO_PROCESS,0)>=15,"nice15 required");require(std::getenv("OMP_NUM_THREADS")&&std::string(std::getenv("OMP_NUM_THREADS"))=="1","one thread required");require(argc==2,"output directory required");fs::path out(argv[1]);require(!fs::exists(out),"fresh evidence directory required");fs::create_directories(out);auto start=std::chrono::steady_clock::now();Json records=Json::array();records.push_back(zero_and_pair());for(auto[n,T]:std::vector<std::pair<double,double>>{{1e16,2},{1e18,2},{1e16,20}}){double lastp=0,laste=0;int lastny=0;for(int ny:{16,32,64,128}){auto row=slab(n,T,ny,out);double pe=row["phi_relative_L2_error"],ee=row["electric_relative_L2_error"];if(lastny){row["phi_observed_order"]=std::log(lastp/pe)/std::log(2.);row["electric_observed_order"]=std::log(laste/ee)/std::log(2.);check(pe<.3*lastp&&ee<.55*laste,"resolved spatial refinement reduces potential and electric error");}lastp=pe;laste=ee;lastny=ny;records.push_back(row);std::ofstream(out/"partial-case-records.json")<<records.dump(2)<<'\n';}}
 rusage usage{};getrusage(RUSAGE_SELF,&usage);Json j={{"cpu_affinity",{7}},{"nice",getpriority(PRIO_PROCESS,0)},{"OMP_NUM_THREADS",std::getenv("OMP_NUM_THREADS")},{"max_rss_kib",usage.ru_maxrss},{"user_cpu_s",usage.ru_utime.tv_sec+usage.ru_utime.tv_usec/1e6},{"system_cpu_s",usage.ru_stime.tv_sec+usage.ru_stime.tv_usec/1e6},{"status","passed"},{"case_records",records},{"checks",checks},{"check_count",checks.size()},{"CPU_only",true},{"native_source_modified",false},{"no_H2O_or_foil_validation_claim",true},{"elapsed_s",std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()}};std::ofstream(out/"results.json")<<j.dump(2)<<'\n';std::cout<<Json{{"status","passed"},{"checks",checks.size()},{"records",records.size()},{"elapsed_s",j["elapsed_s"]}}.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
